# Web BFF using GraphQL
# schema.graphql
type ProductPage {
  product: Product!
  inventory: Inventory!
  pricing: Pricing!
  recommendations: [Product]!
}

# Resolver aggregates from multiple services
const resolvers = {
  ProductPage: {
    product: () => productService.getProduct(parent.id),
    inventory: () => inventoryService.getInventory(parent.id),
    pricing: () => pricingService.getPricing(parent.id),
    recommendations: () => recommendationService.getRecommendations(parent.id)
  }
}
